"""
Unit tests for MILP network solver.
"""
from supply_chain_risk.optimizer import NetworkCostOptimizer

def test_network_optimization_solution():
    suppliers = ["S1", "S2"]
    warehouses = ["W1", "W2"]
    capacity = {"S1": 500.0, "S2": 500.0}
    demand = {"W1": 300.0, "W2": 400.0}
    costs = {
        "S1": {"W1": 2.0, "W2": 4.0},
        "S2": {"W1": 3.0, "W2": 1.0}
    }

    result = NetworkCostOptimizer.solve_network(suppliers, warehouses, capacity, demand, costs)
    assert result["status"] == "Optimal"
    assert result["total_cost"] == (300.0 * 2.0) + (400.0 * 1.0)  # 600 + 400 = 1000
